import itertools
from collections import defaultdict

def calculate_Q(x, y, z, a, b, c):
    """Calculates Q(a, b, c) for a given triplet (x, y, z)."""
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# 1. Fix the first query Q1 = Q(0, 0, 0)
a1, b1, c1 = 0, 0, 0

# 2. Iterate through all possible second queries Q2 = Q(a, b, c)
# We iterate over a, b, c from 0 to 9.
def check_query(a2, b2, c2):
    # Dictionary structure: { (S, Q2_value): list_of_triplets }
    # S = (Q1)/2
    mapping = defaultdict(list)

    for x in range(10):
        for y in range(10):
            for z in range(10):
                triplet = (x, y, z)

                # Calculate Q1 (determines S)
                q1 = calculate_Q(x, y, z, a1, b1, c1)
                S = q1 // 2

                # Calculate Q2
                q2 = calculate_Q(x, y, z, a2, b2, c2)

                key = (S, q2)
                mapping[key].append(triplet)

    # Check for collisions: if any list has length > 1, there is ambiguity.
    for key, triplets in mapping.items():
        if len(triplets) > 1:
            # Collision found
            return False, key, triplets

    # No collisions found
    return True, None, None

# Systematically check Q2 = Q(a2, b2, c2) for a2, b2, c2 in [0, 9]
found_solution = False
best_query = None

# Iterate through all 1000 possible choices for (a2, b2, c2)
for a2 in range(10):
    for b2 in range(10):
        for c2 in range(10):
            if a2 == 0 and b2 == 0 and c2 == 0:
                # Skip Q1 itself
                continue

            is_unique, key, collisions = check_query(a2, b2, c2)

            if is_unique:
                found_solution = True
                best_query = (a2, b2, c2)
                # Since we are looking for *a* pair, we can stop at the first successful one
                break
        if found_solution:
            break
    if found_solution:
        break

if found_solution:
    print(f"Solution found: Q1=(0, 0, 0) and Q2={best_query}")
else:
    print("No solution found in the search space [0, 9]^3 for Q2.")

